insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 15, 10, 'Juntaram-se, pois, em Jerusalém no mês terceiro do ano décimo quinto do reinado de Asa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 15, 11, 'E naquele mesmo dia sacrificaram ao SENHOR, dos despojos que haviam trazido, setecentos bois e sete mil ovelhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 15, 12, 'E entraram em concerto de que buscariam ao SENHOR o Deus de seus pais, de todo seu coração e de toda sua alma;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 15, 13, 'E que qualquer um que não buscasse ao SENHOR o Deus de Israel, morresse, grande ou pequeno, homem ou mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 15, 14, 'E juraram ao SENHOR com grande voz e júbilo, a som de trombetas e de buzinas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 15, 15, 'Do qual juramento todos os de Judá se alegraram; porque de todo o seu coração o juravam, e de toda sua vontade o buscavam: e foi achado deles; e deu-lhes o SENHOR repouso de todas partes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 15, 16, 'E ainda a Maaca mãe do rei Asa, ele mesmo a depôs de sua dignidade, porque havia feito um ídolo no bosque: e Asa destruiu seu ídolo, e o despedaçou, e queimou no ribeiro de Cedrom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 15, 17, 'Mas com tudo isso os altos não foram tirados de Israel, ainda que o coração de Asa tenha sido íntegro enquanto viveu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 15, 18, 'E meteu na casa de Deus o que seu pai havia dedicado, e o que ele havia consagrado, prata e ouro e vasos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 15, 19, 'E não havia guerra até os trinta e cinco anos do reinado de Asa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 16, 1, 'No ano trinta e seis do reinado de Asa, subiu Baasa rei de Israel contra Judá, e edificou a Ramá, para não deixar sair nem entrar a ninguém ao rei Asa, rei de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 16, 2, 'Então tirou Asa a prata e o ouro dos tesouros da casa do SENHOR e da casa real, e enviou a Ben-Hadade rei da Síria, que estava em Damasco, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 16, 3, 'Haja aliança entre mim e ti, como a havia entre meu pai e teu pai; eis que eu te enviei prata e ouro, para que venhas e desfaças a aliança que tens com Baasa rei de Israel, a fim de que se retire de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 16, 4, 'E consentiu Ben-Hadade com o rei Asa, e enviou os capitães de seus exércitos à cidades de Israel: e atacaram a Ijom, Dã, e Abel-Maim, e as cidades fortes de Naftali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 16, 5, 'E ouvindo isto Baasa, cessou de edificar a Ramá, e deixou sua obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 16, 6, 'Então o rei Asa tomou a todo Judá, e levaram-se de Ramá a pedra e madeira com que Baasa edificava, e com ela edificou a Geba e Mispá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 16, 7, 'Naquele tempo veio Hanani vidente a Asa rei de Judá, e disse-lhe: Por quanto te apoiaste no rei de Síria, e não te apoiaste no SENHOR teu Deus, por isso o exército do rei da Síria escapou de tuas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 16, 8, 'Os etíopes e os líbios, não eram um exército numerosíssimo, com carros e muitos cavaleiros? Contudo, porque te apoiaste no SENHOR, ele os entregou em tuas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 16, 9, 'Porque os olhos do SENHOR contemplam toda a terra, para corroborar aos que têm coração íntegro com ele. Loucamente fizeste nisso; porque de agora em diante haverá guerra contra ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 16, 10, 'E irou-se Asa contra o vidente, lançou-o na casa do cárcere, porque foi em extremo incomodado por causa disto. E oprimiu Asa naquele tempo alguns do povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 16, 11, 'Mas eis que, os feitos de Asa, primeiros e últimos, estão escritos no livro dos reis de Judá e de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 16, 12, 'E o ano trinta e nove de seu reinado enfermou Asa dos pés para acima, e em sua enfermidade não buscou ao SENHOR, mas sim aos médicos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 16, 13, 'E descansou Asa com seus pais, e morreu no ano quarenta e um de seu reinado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 16, 14, 'E sepultaram-no em seus sepulcros que ele havia feito para si na cidade de Davi; e puseram-no em uma cama, a qual encheram de aromas e artefatos com fragrâncias, preparadas por perfumistas; e fizeram uma grande fogueira em sua homenagem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 17, 1, 'E reinou em seu lugar Josafá seu filho, o qual prevaleceu contra Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 17, 2, 'E pôs exército em todas as cidades fortes de Judá, e colocou gente de guarnição, em terra de Judá, e também nas cidades de Efraim que seu pai Asa havia tomado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 17, 3, 'E foi o SENHOR com Josafá, porque andou nos primeiros caminhos de Davi seu pai, e não buscou aos baalins;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 17, 4, 'mas buscou o Deus de seu pai, e andou em seus mandamentos, e não segundo as obras de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 17, 5, 'Por isso o SENHOR confirmou o reino em sua mão, e todo Judá deu presentes a Josafá; e teve riquezas e glória em abundância.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 17, 6, 'E animou-se seu coração nos caminhos do SENHOR, e tirou os altos e os bosques de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 17, 7, 'Ao terceiro ano de seu reinado enviou seus príncipes Bene-Hail, Obadias, Zacarias, Natanael e Micaías, para que ensinassem nas cidades de Judá;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 17, 8, 'E com eles aos levitas, Semaías, Netanias, Zebadias, e Asael, e Semiramote, e Jônatas, e Adonias, e Tobias, e Tobadonias, levitas; e com eles a Elisama e a Jorão, sacerdotes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 17, 9, 'E ensinaram em Judá, tendo consigo o livro da lei do SENHOR, e rodearam por todas as cidades de Judá ensinando ao povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 17, 10, 'E caiu o pavor do SENHOR sobre todos os reinos das terras que estavam ao redor de Judá; que não ousaram fazer guerra contra Josafá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 17, 11, 'E dos filisteus traziam presentes a Josafá, e tributos de prata. Os árabes também lhe trouxeram gado: sete mil e setecentos carneiros e sete mil e setecentos bodes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 17, 12, 'Ia pois Josafá crescendo altamente: e edificou em Judá fortalezas e cidades de depósitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 17, 13, 'Teve ademais muitas obras nas cidades de Judá, e homens de guerra muito valentes em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 17, 14, 'E este é o número deles segundo as casas de seus pais: em Judá, chefes dos milhares: o general Adna, e com ele trezentos mil homens muito esforçados;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 17, 15, 'Depois dele, o chefe Joanã, e com ele duzentos e oitenta mil;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 17, 16, 'Depois este, Amasias filho de Zicri, o qual se havia oferecido voluntariamente ao SENHOR, e com ele duzentos mil homens valentes;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 17, 17, 'De Benjamim, Eliada, homem muito valente, e com ele duzentos mil armados de arco e escudo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 17, 18, 'Depois este, Jozabade, e com ele cento e oitenta mil preparados para a guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 17, 19, 'Estes eram servos do rei, sem os que havia o rei posto nas cidades de guarnição por toda Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 1, 'Tinha, pois, Josafá riquezas e glória em abundância, e estabeleceu parentesco com Acabe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 2, 'E depois de alguns anos desceu a Acabe a Samaria; por o que matou Acabe muitas ovelhas e bois para ele, e para a gente que com ele vinha: e persuadiu-lhe que fosse com ele a Ramote de Gileade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 3, 'E disse Acabe rei de Israel a Josafá rei de Judá: Queres vir comigo a Ramote de Gileade? E ele respondeu: Como eu, assim também tu; e como teu povo, assim também meu povo: iremos contigo à guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 4, 'Ademais disse Josafá ao rei de Israel: Rogo-te que consultes hoje a palavra do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 5, 'Então o rei de Israel juntou quatrocentos profetas, e disse-lhes: Iremos à guerra contra Ramote de Gileade, ou ficarei eu quieto? E eles disseram: Sobe, que Deus os entregará em mão do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 6, 'Mas Josafá disse: Há ainda aqui algum profeta do SENHOR, para que por ele perguntemos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 7, 'E o rei de Israel respondeu a Josafá: Ainda há aqui um homem pelo qual podemos preguntar ao SENHOR: mas eu lhe aborreço, porque nunca me profetiza coisa boa, a não ser sempre mal. Este é Micaías, filho de Inlá. E respondeu Josafá: Não fale assim o rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 8, 'Então o rei de Israel chamou um eunuco, e disse-lhe: Faze vir logo a Micaías filho de Inlá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 9, 'E o rei de Israel e Josafá rei de Judá, estavam sentados cada um em seu trono, vestidos de suas roupas; e estavam sentados na eira à entrada da porta de Samaria, e todos os profetas profetizavam diante deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 10, 'E Zedequias filho de Quenaaná se havia feito chifres de ferro, e dizia: Assim disse o SENHOR: Com estes chifrarás aos sírios até destruí-los de todo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 11, 'De esta maneira profetizavam também todos os profetas, dizendo: Sobe a Ramote de Gileade, e sei próspero; porque o SENHOR a entregará em mão do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 12, 'E o mensageiro que havia ido a chamar a Micaías, lhe falou, dizendo: Eis aqui as palavras dos profetas a uma boca anunciam ao rei bens; eu, pois, te rogo que tua palavra seja como a de um deles, que fales bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 13, 'E disse Micaías: Vive o SENHOR, que o que meu Deus me disser, isso falarei. E veio ao rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 14, 'E o rei lhe disse: Micaías, iremos a lutar contra Ramote de Gileade, ou ficarei eu quieto? E ele respondeu: Subi, que sereis prosperados, que serão entregues em vossas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 15, 'E o rei lhe disse: Até quantas vezes te conjurarei pelo nome do SENHOR que não me fales a não ser a verdade?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 16, 'Então ele disse: Eis visto a todo Israel derramado pelos montes como ovelhas sem pastor: e disse o SENHOR: Estes não têm senhor; volte-se cada um em paz em sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 17, 'E o rei de Israel disse a Josafá: Não te havia eu dito que não me profetizaria bem, mas sim mal?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 18, 'Então ele disse: Ouvi, pois, a palavra do SENHOR: Eu vi ao SENHOR sentado em seu trono, e todo o exército dos céus estava a sua mão direita e a sua esquerda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 19, 'E o SENHOR disse: Quem induzirá a Acabe rei de Israel, para que suba e caia em Ramote de Gileade? E um dizia assim, e outro dizia de outra maneira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 20, 'Mas saiu um espírito, que se pôs diante do SENHOR, e disse: Eu lhe induzirei. E o SENHOR lhe disse: De que modo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 21, 'E ele disse: Sairei e serei espírito de mentira na boca de todos os profetas. E o SENHOR disse: Incita, e também prevalece: sai, e faze-o assim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 22, 'E eis que agora pôs o SENHOR espírito de mentira na boca destes teus profetas; mas o SENHOR decretou o mal acerca de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 23, 'Então Zedequias filho de Quenaaná se chegou a ele, e feriu a Micaías na face, e disse: Por que caminho se separou de mim o espírito do SENHOR para falar a ti?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 24, 'E Micaías respondeu: Eis aqui tu o verás aquele dia, quando te entrarás de câmara em câmara para esconder-te.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 25, 'Então o rei de Israel disse: Tomai a Micaías, e voltai-o a Amom governador da cidade, e a Joás filho do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 26, 'E direis: O rei disse assim: Ponde a este no cárcere, e sustentai-lhe com pão de aflição e água de angústia, até que eu volte em paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 27, 'E Micaías disse: Se tu voltares em paz, o SENHOR não falou por mim. Disse ademais: Ouvi o, povos todos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 28, 'Subiu, pois, o rei de Israel, e Josafá rei de Judá, a Ramote de Gileade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 29, 'E disse o rei de Israel a Josafá: Eu me disfarçarei para entrar na batalha: mas tu veste-te tuas roupas. E disfarçou-se o rei de Israel, e entrou na batalha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 30, 'Havia o rei de Síria mandado aos capitães dos carros que tinha consigo, dizendo: Não luteis com pequeno nem com grande, a não ser somente com o rei de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 31, 'E como os capitães dos carros viram a Josafá, disseram: Este é o rei de Israel. E cercaram-no para lutar; mas Josafá clamou, e ajudou-o o SENHOR, e apartou-os Deus dele:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 32, 'Pois vendo os capitães dos carros que não era o rei de Israel, desistiram de persegui-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 33, 'Mas disparando um o arco ao acaso, feriu ao rei de Israel entre as junturas e a armadura. Ele então disse ao condutor do carro: Volta tua mão, e tira-me do campo, porque estou gravemente ferido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 18, 34, 'E intensificou a batalha aquele dia, por o que esteve o rei de Israel em pé no carro em frente dos sírios até a tarde; mas morreu a pôr do sol.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 19, 1, 'E Josafá rei de Judá se voltou em paz a sua casa em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 19, 2, 'E saiu-lhe ao encontro Jeú o vidente, filho de Hanani, e disse ao rei Josafá: Ao ímpio dás ajuda, e amas aos que aborrecem ao SENHOR? Pois a ira da presença do SENHOR será sobre ti por ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 19, 3, 'Porém se acharam em ti boas coisas, porque cortaste da terra os bosques, e dispuseste tua coração a buscar a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 19, 4, 'Habitou, pois, Josafá em Jerusalém; mas dava volta e saía ao povo, desde Berseba até o monte de Efraim, e os reconduzia ao SENHOR, o Deus de seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 19, 5, 'E pôs na terra juízes em todas as cidades fortes de Judá, por todos os lugares.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 19, 6, 'E disse aos juízes: Olhai o que fazeis: porque não julgueis em lugar de homem, mas sim em lugar do SENHOR, o qual está convosco no negócio do juízo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 19, 7, 'Seja, pois, convosco o temor do SENHOR; guardai e fazei: porque no SENHOR nosso Deus não há iniquidade, nem acepção de pessoas, nem receber suborno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 19, 8, 'E pôs também Josafá em Jerusalém alguns dos levitas e sacerdotes, e dos pais de famílias de Israel, para o juízo do SENHOR e para as causas. E voltaram a Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 19, 9, 'E mandou-lhes, dizendo: Procedereis assim com temor do SENHOR, com verdade, e com coração íntegro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 19, 10, 'Em qualquer causa que vier a vós de vossos irmãos que habitam nas cidades, entre sangue e sangue, entre lei e preceito, estatutos e direitos, haveis de admoestar-lhes que não pequem contra o SENHOR, porque não venha ira sobre vós e sobre vossos irmãos. Agindo assim, não pecareis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 19, 11, 'E eis que Amarias sacerdote será o que vos presida em todo negócio do SENHOR; e Zebadias filho de Ismael, príncipe da casa de Judá, em todos os negócios do rei; também os levitas serão oficiais em presença de vós. Esforçai-vos, pois, e agi; porque o SENHOR estará com quem é bom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 1, 'Passadas estas coisas, aconteceu que os filhos de Moabe e de Amom, e com eles outros dos amonitas, vieram contra Josafá à guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 2, 'E acudiram, e deram aviso a Josafá, dizendo: Contra ti vem uma grande multidão da outra parte do mar, e da Síria; e eis que eles estão em Hazazom-Tamar, que é En-Gedi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 3, 'Então ele teve temor; e pôs Josafá seu rosto para consultar ao SENHOR, e fez apregoar jejum a todo Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 4, 'E juntaram-se os de Judá para pedir socorro ao SENHOR: e também de todas as cidades de Judá vieram a pedir ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 5, 'Pôs-se então Josafá em pé na reunião de Judá e de Jerusalém, na casa do SENHOR, diante do átrio novo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 6, 'E disse: o SENHOR Deus de nossos pais, não és tu Deus nos céus, e te ensenhoreias em todos os reinos das nações? não está em tua mão tal força e potência, que não há quem te resista?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 7, 'Deus nosso, não lançaste tu os moradores desta terra diante de teu povo Israel, e a deste à semente de Abraão tua amigo para sempre?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 8, 'E eles habitaram nela, e te edificaram nela santuário a teu nome, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 9, 'Se mal vier sobre nós, ou espada de castigo, ou pestilência, ou fome, nos apresentaremos diante desta casa, e diante de ti, (porque teu nome está em esta casa,) e de nossas tribulações clamaremos a ti, e tu nos ouvirás e salvarás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 10, 'Agora, pois, eis que os filhos de Amom e de Moabe, e os do monte de Seir, à terra dos quais nem quiseste que passasse Israel quando vinham da terra do Egito, mas sim que se afastassem deles, e não os destruíssem;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 11, 'Eis que eles nos dão o pago, vindo a lançar-nos de tua herdade, que tu nos deste a possuir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 12, 'Ó Deus nosso! Não os julgarás tu? Porque em nós não há força contra tão grande multidão que vem contra nós: não sabemos o que devemos fazer, mas a ti voltamos nossos olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 13, 'E todo Judá estava em pé diante do SENHOR, com seus meninos, e suas mulheres, e seus filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 14, 'E estava ali Jaaziel filho de Zacarias, filho de Benaia, filho de Jeiel, filho de Matanias, levita dos filhos de Asafe, sobre o qual veio o espírito do SENHOR em meio da reunião;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 15, 'E disse: Ouvi, Judá todo, e vós moradores de Jerusalém, e tu, rei Josafá. o SENHOR vos diz assim: Não temais nem vos amedronteis diante desta tão grande multidão; porque não é vossa a guerra, mas sim de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 16, 'Amanhã descereis contra eles: eis que eles subirão pela encosta de Ziz, e os achareis junto ao ribeiro, antes do deserto de Jeruel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 17, 'Não haverá para que vós luteis em este caso: parai-vos, ficai parados, e vede a salvação do SENHOR convosco. Ó Judá e Jerusalém, não temais nem desmaieis; saí amanhã contra eles, que o SENHOR será convosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 18, 'Então Josafá se inclinou rosto por terra, e também todo Judá e os moradores de Jerusalém se prostraram diante do SENHOR, e adoraram ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 19, 'E levantaram-se os levitas dos filhos de Coate e dos filhos de Corá, para louvar ao SENHOR o Deus de Israel a grande e alta voz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 20, 'E quando se levantaram pela manhã, saíram pelo deserto de Tecoa. E enquanto eles saíam, Josafá estando em pé, disse: Ouvi-me, Judá e moradores de Jerusalém. Crede no SENHOR vosso Deus, e sereis seguros; crede em seus profetas, e sereis prosperados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 21, 'E havido conselho com o povo, pôs a alguns que cantassem ao SENHOR, e louvassem na formosura da santidade, enquanto que saía a gente armada, e dissessem: Glorificai ao SENHOR, porque sua misericórdia é para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 22, 'E quando começaram com clamor e com louvor, pôs o SENHOR contra os filhos de Amom, de Moabe, e do monte de Seir, as emboscadas deles mesmos que vinham contra Judá, e mataram-se os uns aos outros:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 23, 'Pois os filhos de Amom e Moabe se levantaram contra os do monte de Seir, para matá-los e destruí-los; e quando houveram acabado aos do monte de Seir, cada qual ajudou à destruição de seu companheiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 24, 'E logo que veio Judá ao posto de observação do deserto, olharam até a multidão; mas eis que jaziam eles em terra mortos, que ninguém havia escapado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 25, 'Vindo então Josafá e seu povo a despojá-los, acharam neles muitas riquezas entre os cadáveres, assim vestidos como preciosos utensílios, os quais tomaram para si, tantos, que não os podiam levar: três dias durou o despojo, porque era muito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 26, 'E ao quarto dia se juntaram no vale de Beraca; porque ali bendisseram ao SENHOR, e por isto chamaram o nome daquele lugar o vale de Beraca, até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 27, 'E todo Judá e os de Jerusalém, e Josafá à cabeça deles, voltaram a Jerusalém com alegria, porque o SENHOR lhes havia dado alegria de seus inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 28, 'E vieram a Jerusalém com saltérios, harpas, e buzinas, à casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 29, 'E foi o pavor de Deus sobre todos os reinos daquela terra, quando ouviram que o SENHOR havia pelejado contra os inimigos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 30, 'E o reino de Josafá teve repouso; porque seu Deus lhe deu repouso de todas partes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 31, 'Assim reinou Josafá sobre Judá: de trinta e cinco anos era quando começou a reinar, e reinou vinte e cinco anos em Jerusalém. O nome de sua mãe foi Azuba, filha de Sili.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 32, 'E andou no caminho de Asa seu pai, sem desviar-se dele, fazendo o que era correto aos olhos do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 33, 'Com tudo isso os altos não foram tirados; que o povo ainda não havia preparado seu coração ao Deus de seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 34, 'Os demais dos feitos de Josafá, primeiros e últimos, eis que estão escritos nas palavras de Jeú filho de Hanani, do qual é feita menção no livro dos reis de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 35, 'Passadas estas coisas, Josafá rei de Judá estabeleceu amizade com Acazias rei de Israel, o qual foi dado à impiedade:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 36, 'E fez com ele companhia para preparar navios que fossem a Társis; e construíram os navios em Eziom-Geber.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 20, 37, 'Então Eliézer filho de Dodava de Maressa, profetizou contra Josafá, dizendo: Por quanto fizeste companhia com Acazias, o SENHOR destruirá tuas obras. E os navios se romperam, e não puderam ir a Társis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 21, 1, 'E descansou Josafá com seus pais, e sepultaram-no com seus pais na cidade de Davi. E reinou em seu lugar Jeorão seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 21, 2, 'Este teve irmãos, filhos de Josafá, a Azarias, Jeiel, Zacarias, Azarias, Micael, e Sefatias. Todos estes foram filhos de Josafá rei de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 21, 3, 'E seu pai lhes havia dado muitos presentes de ouro e de prata, e coisas preciosas, e cidades fortes em Judá; mas havia dado o reino a Jeorão, porque ele era o primogênito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 21, 4, 'Foi, pois, elevado Jeorão ao reino de seu pai; e logo que se fez forte, matou à espada a todos seus irmãos, e também alguns dos príncipes de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 21, 5, 'Quando começou a reinar era de trinta e dois anos, e reinou oito anos em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 21, 6, 'E andou no caminho dos reis de Israel, como fez a casa de Acabe; porque tinha por mulher a filha de Acabe, e fez o que era mau aos olhos do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 21, 7, 'Mas o SENHOR não quis destruir a casa de Davi, a causa da aliança que com Davi havia feito, e porque lhe havia dito que lhe daria lâmpada a ele e a seus filhos perpetuamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 21, 8, 'Em os dias deste se rebelou Edom, para não estar sob o poder de Judá, e puseram rei sobre si.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 21, 9, 'Então passou Jeorão com seus príncipes, e consigo todos seus carros; e levantou-se de noite, e feriu aos edomitas que lhe haviam cercado, e a todos os comandantes de seus carros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 21, 10, 'Com tudo isso Edom ficou rebelado, sem estar sob a mão de Judá até hoje. Também se rebelou no mesmo tempo Libna para não estar sob sua mão; porquanto ele havia deixado ao SENHOR o Deus de seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 21, 11, 'Além disto, fez altos nos montes de Judá, e fez que os moradores de Jerusalém fornicassem, e a ele impeliu a Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 21, 12, 'E vieram-lhe letras do profeta Elias, que diziam: o SENHOR, o Deus de Davi teu pai, disse assim: Por quanto não andaste nos caminhos de Josafá teu pai, nem nos caminhos de Asa, rei de Judá,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 21, 13, 'Antes andaste no caminho dos reis de Israel, e fizeste que fornicasse Judá, e os moradores de Jerusalém, como fornicou a casa de Acabe; e ademais mataste a teus irmãos, à família de teu pai, os quais eram melhores que tu:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 21, 14, 'Eis que o SENHOR ferirá teu povo de uma grande praga, e a teus filhos e a tuas mulheres, e a toda tua riqueza;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 21, 15, 'E a ti com muitas enfermidades, com enfermidade de tuas entranhas, até que as entranhas saiam de ti por causa da enfermidade de cada dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 21, 16, 'Então despertou o SENHOR contra Jeorão o espírito dos filisteus, e dos árabes que estavam junto aos etíopes;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 21, 17, 'E subiram contra Judá, e invadiram a terra, e tomaram toda a riqueza que acharam na casa do rei, e a seus filhos, e a suas mulheres; que não lhe restou filho, a não ser Jeoacaz o menor de seus filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 21, 18, 'Depois de tudo isto o SENHOR o feriu nas entranhas de uma enfermidade incurável.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 21, 19, 'E aconteceu que, passando um dia atrás outro, ao fim, ao fim de dois anos, as entranhas se lhe saíram com a enfermidade, morrendo assim de enfermidade muito penosa. E seu povo não fez queima em homenagem a ele, como haviam feito a seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 21, 20, 'Quando começou a reinar era de trinta e dois anos, e reinou em Jerusalém oito anos; e se foi sem deixar saudades. E sepultaram-no na cidade de Davi, mas não nos sepulcros dos reis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 22, 1, 'E os moradores de Jerusalém fizeram rei em lugar seu a Acazias seu filho menor: porque a tropa havia vindo com os árabes ao campo, havia morto a todos os maiores; por o qual reinou Acazias, filho de Jeorão rei de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 22, 2, 'Quando Acazias começou a reinar era de quarenta e dois anos, e reinou um ano em Jerusalém. O nome de sua mãe foi Atalia, filha de Onri.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 22, 3, 'Também ele andou nos caminhos da casa de Acabe: porque sua mãe lhe aconselhava a agir impiamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 22, 4, 'Fez, pois, o que era mau aos olhos do SENHOR, como a casa de Acabe; porque depois da morte de seu pai, eles lhe aconselharam para sua perdição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 22, 5, 'E ele andou nos conselhos deles, e foi à guerra com Jeorão filho de Acabe, rei de Israel, contra Hazael rei da Síria, a Ramote de Gileade, de onde os sírios feriram a Jeorão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 22, 6, 'E se voltou para curar-se em Jezreel das feridas que lhe haviam feito em Ramá, lutando com Hazael rei da Síria. E desceu Azarias filho de Jeorão, rei de Judá, a visitar a Jeorão filho de Acabe, em Jezreel, porque ali estava enfermo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 22, 7, 'Isto, porém, vinha de Deus, para que Acazias fosse abatido vindo a Jeorão: porque sendo vindo, saiu com Jeorão contra Jeú filho de Ninsi, ao qual o SENHOR havia ungido para que exterminasse a casa de Acabe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 22, 8, 'E foi que, fazendo juízo Jeú com a casa de Acabe, achou aos príncipes de Judá, e aos filhos dos irmãos de Acazias, que serviam a Acazias, e matou-os.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 22, 9, 'E buscando a Acazias, o qual se havia escondido em Samaria, tomaram-no, e trouxeram-no a Jeú, e lhe mataram; e deram-lhe sepultura, porque disseram: É filho de Josafá, o qual buscou ao SENHOR de todo seu coração. E a casa de Acazias não tinha forças para para manter o reino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 22, 10, 'Então Atalia mãe de Acazias, vendo que seu filho era morto, levantou-se e destruiu toda a descendência real da casa de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 22, 11, 'Porém Jeosebate, filha do rei, tomou a Joás filho de Acazias, e tirou-o dentre os filhos do rei, que foram mortos, e guardou a ele e a sua ama na câmara dos leitos. Assim pois o escondeu Jeosebate, filha do rei Jeorão, mulher de Joiada o sacerdote, (porque ela era irmã de Acazias), de diante de Atalia, e não o mataram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 22, 12, 'E esteve com eles escondido na casa de Deus durante seis anos. E Atalia reinava naquela terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 23, 1, 'Mas no sétimo ano Joiada se esforçou, e tomou consigo em aliança aos comandantes de cem, Azarias, filho de Jeroão, e a Ismael, filho de Joanã, e a Azarias, filho de Obede, e a Maaseias, filho de Adaías, e a Elisafate, filho de Zicri;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 23, 2, 'Os quais rodeando por Judá, juntaram os levitas de todas as cidades de Judá, e aos príncipes das famílias de Israel, e vieram a Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 23, 3, 'E toda a multidão fez aliança com o rei na casa de Deus. E ele lhes disse: Eis que o filho do rei, o qual reinará, como o SENHOR o tem dito dos filhos de Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 23, 4, 'O que haveis de fazer é: a terceira parte de vós, os que entram de semana, estarão de porteiros com os sacerdotes e os levitas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 23, 5, 'E a terceira parte, à casa do rei; e a terceira parte, à porta do fundamento: e todo o povo estará nos pátios da casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 23, 6, 'E ninguém entre na casa do SENHOR, a não ser os sacerdotes e levitas que servem: estes entrarão, porque estão consagrados; e todo o povo fará a guarda do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 23, 7, 'E os levitas rodearão ao rei por todas as partes, e cada um terá suas armas na mão; e qualquer um que entrar na casa, morra: e estareis com o rei quando entrar, e quando sair.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 23, 8, 'E os levitas e todo Judá o fizeram tudo como o havia mandado o sacerdote Joiada: e tomou cada um os seus, os que entravam de semana, e os que saíam o sábado: porque o sacerdote Joiada não deu licença às companhias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 23, 9, 'Deu também o sacerdote Joiada aos comandantes de cem as lanças, paveses e escudos que haviam sido do rei Davi, que estavam na casa de Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 23, 10, 'E pôs em ordem a todo o povo, tendo cada um sua espada na mão, desde o canto direito do templo até o esquerdo, até o altar e a casa, em derredor do rei por todas as partes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 23, 11, 'Então tiraram ao filho do rei, e puseram-lhe a coroa e o testemunho, e fizeram-lhe rei; e Joiada e seus filhos lhe ungiram, dizendo logo: Viva o rei!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 23, 12, 'E quando Atalia ouviu o estrondo da gente que corria, e dos que bendiziam ao rei, veio ao povo à casa do SENHOR;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 23, 13, 'E olhando, viu ao rei que estava junto a sua coluna à entrada, e os príncipes e os trombetas junto ao rei, e que todo o povo da terra fazia alegrias, e soavam buzinas, e cantavam com instrumentos de música os que sabiam louvar. Então Atalia rasgou seus vestidos, e disse: Traição! Traição!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 23, 14, 'E tirando o sacerdote Joiada os comandantes de cem e capitães do exército, disse-lhes: Tirai-a fora do recinto; e o que a seguir, morra à espada: porque o sacerdote havia mandado que não a matassem na casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 23, 15, 'Eles, pois, a detiveram, e logo que havia ela passado a entrada da porta dos cavalos da casa do rei, ali a mataram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 23, 16, 'E Joiada fez pacto entre si e todo o povo e o rei, que seriam povo do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 23, 17, 'Depois disto entrou todo o povo no templo de Baal, e derrubaram-no, e também seus altares; e fizeram pedaços suas imagens, e mataram diante dos altares a Matã, sacerdote de Baal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 23, 18, 'Logo ordenou Joiada os ofícios na casa do SENHOR sob a mão dos sacerdotes e levitas, segundo Davi os havia distribuído na casa do SENHOR, para oferecer ao SENHOR os holocaustos, como está escrito na lei de Moisés, com alegria e cantares, conforme a ordenação de Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 23, 19, 'Pôs também porteiros às portas da casa do SENHOR, para que por nenhuma via entrasse nenhum imundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 23, 20, 'Tomou depois os comandantes de cem, e os principais, e os que governavam o povo; e a todo o povo da terra, e levou ao rei da casa do SENHOR; e vindo até o meio da porta maior da casa do rei, assentaram ao rei sobre o trono do reino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 23, 21, 'E todo o povo daquela terra se alegrou; e a cidade ficou em paz, depois de terem matado Atalia à espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 24, 1, 'De sete anos era Joás quando começou a reinar, e quarenta anos reinou em Jerusalém. O nome de sua mãe foi Zíbia, de Berseba.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 24, 2, 'E fez Joás o que era correto aos olhos do SENHOR todos os dias de Joiada o sacerdote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 24, 3, 'E tomou para ele Joiada duas mulheres; e gerou filhos e filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 24, 4, 'Depois disto aconteceu que Joás teve vontade de reparar a casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 24, 5, 'E juntou os sacerdotes e os levitas, e disse-lhes: Saí pelas cidades de Judá, e juntai dinheiro de todo Israel, para que cada ano seja reparada a casa de vosso Deus; e vós ponde diligência no negócio. Mas os levitas não puseram diligência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 24, 6, 'Por isso o rei chamou a Joiada o principal, e disse-lhe: Por que não procuraste que os levitas tragam de Judá e de Jerusalém ao tabernáculo do testemunho, a oferta que impôs Moisés servo do SENHOR, e da congregação de Israel?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 24, 7, 'Porque a ímpia Atalia e seus filhos haviam destruído a casa de Deus, e ademais haviam gastado nos ídolos todas as coisas consagradas à casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 24, 8, 'Mandou, pois, o rei que fizessem uma arca, a qual puseram fora à porta da casa do SENHOR;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 24, 9, 'E fizeram apregoar em Judá e em Jerusalém, que trouxessem ao SENHOR a oferta que Moisés servo de Deus havia imposto a Israel no deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 24, 10, 'E todos os príncipes e todo o povo se alegraram: e traziam, e lançavam no arca até enchê-la.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 24, 11, 'E quando vinha o tempo para levar a arca ao magistrado do rei por mão dos levitas, quando viam que havia muito dinheiro, vinha o escriba do rei, e o que estava posto pelo sumo sacerdote, e levavam a arca, e esvaziavam-na, e traziam-na de volta a seu lugar; e assim o faziam a cada dia, e recolhiam muito dinheiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 24, 12, 'O qual dava o rei e Joiada aos que faziam a obra do serviço da casa do SENHOR, e tomavam pedreiros e oficiais que reparassem a casa do SENHOR, e ferreiros e artesãos de metal para compor a casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 24, 13, 'Faziam, pois, os oficiais a obra, e por suas mãos foi a obra restaurada, e restituíram a casa de Deus a sua condição, e a consolidaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 24, 14, 'E quando houveram acabado, trouxeram o que restava do dinheiro ao rei e a Joiada, e fizeram dele vasos para a casa do SENHOR, vasos para o serviço, utensílios para os sacrifícios, colheres, vasos de ouro e de prata. E sacrificavam holocaustos continuamente na casa do SENHOR todos os dias de Joiada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 24, 15, 'Mas Joiada envelheceu, e morreu farto de dias: de cento e trinta anos era quando morreu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 24, 16, 'E sepultaram-no na cidade de Davi com os reis, porquanto havia feito bem com Israel, e para com Deus, e com sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 24, 17, 'Depois de Joiada ter morrido, vieram os príncipes de Judá, e fizeram reverência ao rei; e o rei os ouviu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 24, 18, 'E abandonaram a casa do SENHOR o Deus de seus pais, e serviram aos bosques e às imagens esculpidas; e a ira veio sobre Judá e Jerusalém por este seu pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 24, 19, 'E enviou-lhes profetas, para que os reconduzissem ao SENHOR, os quais lhes protestaram: mas eles não os escutaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 24, 20, 'E o espírito de Deus investiu a Zacarias, filho de Joiada o sacerdote, o qual estando sobre o povo, lhes disse: Assim disse Deus: Por que quebrantais os mandamentos do SENHOR? Não vos virá bem disso; porque por haver deixado ao SENHOR, ele também vos deixará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 24, 21, 'Mas eles fizeram conspiração contra ele, e cobriram-lhe de pedras por mandado do rei, no pátio da casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 24, 22, 'Não teve, pois, memória o rei Joás da misericórdia que seu pai Joiada havia feito com ele, antes matou-lhe seu filho; o qual disse ao morrer: o SENHOR o veja, e o exija.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 24, 23, 'À volta do ano subiu contra ele o exército da Síria; e vieram a Judá e a Jerusalém, e destruíram no povo a todos os principais dele, e enviaram todos seus despojos ao rei a Damasco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 24, 24, 'Porque ainda que o exército da Síria houvesse vindo com pouca gente, o SENHOR lhes entregou em suas mãos um exército muito numeroso; porquanto haviam deixado ao SENHOR o Deus de seus pais. E com Joás fizeram juízos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 24, 25, 'E indo-se dele os sírios, deixaram-no em muitas enfermidades; e conspiraram contra ele seus servos a causa dos sangues dos filhos de Joiada o sacerdote, e feriram-lhe em sua cama, e morreu: e sepultaram-lhe na cidade de Davi, mas não o sepultaram nos sepulcros dos reis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 24, 26, 'Os que conspiraram contra ele foram Zabade, filho de Simeate amonita, e Jozabade, filho de Sin moabita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 24, 27, 'De seus filhos, e da multiplicação que fez das rendas, e da restauração da casa do SENHOR, eis que está escrito na história do livro dos reis. E reinou em seu lugar Amazias seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 25, 1, 'De vinte e cinco anos era Amazias quando começou a reinar, e vinte e nove anos reinou em Jerusalém: o nome de sua mãe foi Jeoadã, de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 25, 2, 'Fez ele o que era correto aos olhos do SENHOR ainda que não de coração íntegro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 25, 3, 'E logo que foi confirmado no reino, matou os seus servos que haviam matado o seu pai, o rei;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 25, 4, 'Mas não matou aos filhos deles, segundo o que está escrito na lei no livro de Moisés, de onde o SENHOR mandou, dizendo: Não morrerão os pais pelos filhos, nem os filhos pelos pais; mas cada um morrerá por seu pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 25, 5, 'Juntou logo Amazias a Judá, e com arranjo às famílias pôs-lhes capitães de milhares e comandantes de cem por todo Judá e Benjamim; e tomou-os por lista de vinte anos acima, e foram achados neles trezentos mil escolhidos para sair à guerra, que tinham lança e escudo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 25, 6, 'E de Israel contratou a dinheiro cem mil homens valentes, por cem talentos de prata.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 25, 7, 'Mas um homem de Deus veio a ele, dizendo-lhe: Rei, não vá contigo o exército de Israel; porque o SENHOR não é com Israel, nem com todos os filhos de Efraim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 25, 8, 'Porém se tu vais, se o fazes, e te esforças para lutar, Deus te fará cair diante dos inimigos; porque em Deus está a força, ou para ajudar, ou para derrubar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 25, 9, 'E Amazias disse ao homem de Deus: Que, pois, se fará de cem talentos que dei ao exército de Israel? E o homem de Deus respondeu: Do SENHOR é dar-te muito mais que isto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 25, 10, 'Então Amazias separou o esquadrão da gente que havia vindo a ele de Efraim, para que se fossem a suas casas: e eles se iraram grandemente contra Judá, e voltaram a suas casas encolerizados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 25, 11, 'Esforçando-se então Amazias, tirou seu povo, e veio ao vale do sal: e feriu dos filhos de Seir dez mil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 25, 12, 'E os filhos de Judá tomaram vivos outros dez mil, os quais levaram ao cume de um penhasco, e dali os atiraram abaixo, e todos se fizeram em pedaços.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 25, 13, 'Porém os do esquadrão que Amazias havia despedido, porque não fossem com ele à guerra, derramaram-se sobre as cidades de Judá, desde Samaria até Bete-Horom, e feriram deles três mil, e tomaram um grande despojo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 25, 14, 'Regressando logo Amasias da matança dos edomitas, trouxe também consigo os deuses dos filhos de Seir, e os pôs para si por deuses, e encurvou-se diante deles, e queimou-lhes incenso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 25, 15, 'Acendeu-se, portanto, o furor do SENHOR contra Amasias, e enviou a ele um profeta, que lhe disse: Por que buscaste os deuses de gente estrangeira, que não livraram a seu povo de tuas mãos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 25, 16, 'E falando-lhe o profeta estas coisas, ele lhe respondeu: Puseram a ti por conselheiro do rei? Deixa-te disso: por que queres que te matem? E ao cessar, o profeta disse logo: Eu sei que Deus decidiu destruir-te, porque fizeste isto, e não obedeceste a meu conselho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 25, 17, 'E Amazias rei de Judá, havido seu conselho, enviou a dizer a Joás, filho de Jeoacaz filho de Jeú, rei de Israel: Vem, e vejamo-nos face a face.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 25, 18, 'Então Joás rei de Israel enviou a dizer a Amazias rei de Judá: O cardo que estava no Líbano, enviou ao cedro que estava no Líbano, dizendo: Da tua filha a meu filho por mulher. E eis que os animais selvagens que estavam no Líbano, passaram, e pisotearam o cardo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 25, 19, 'Tu dizes: Eis que feri a Edom; e teu coração se enaltece para gloriar-te: agora fica-te em tua casa; para que te intrometes em mal, para cair tu e Judá contigo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 25, 20, 'Mas Amasias não quis ouvir; porque isto era da parte de Deus, que queria os entregar nas mãos de seus inimigos, porquanto haviam buscado os deuses de Edom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 25, 21, 'Subiu, pois, Joás rei de Israel, e vieram face a face ele e Amazias rei de Judá, em Bete-Semes, a qual é de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 25, 22, 'Porém caiu Judá diante de Israel, e fugiu cada um a sua morada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 25, 23, 'E Joás rei de Israel prendeu em Bete-Semes a Amazias rei de Judá, filho de Joás filho de Jeoacaz, e levou-o a Jerusalém: e derrubou o muro de Jerusalém desde a porta de Efraim até a porta da esquina, quatrocentos côvados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 25, 24, 'Assim tomou todo o ouro e prata, e todos os vasos que se acharam na casa de Deus em casa de Obede-Edom, e os tesouros da casa do rei, e os filhos dos príncipes, e voltou-se a Samaria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 25, 25, 'E viveu Amazias filho de Joás, rei de Judá, quinze anos depois da morte de Joás filho de Jeoacaz rei de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 25, 26, 'Os demais dos feitos de Amazias, primeiros e últimos, não estão escritos no livro dos reis de Judá e de Israel?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 25, 27, 'Desde aquele tempo que Amazias se separou do SENHOR, maquinaram contra ele conspiração em Jerusalém; e havendo ele fugido a Laquis, enviaram atrás ele a Laquis, e ali o mataram;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 25, 28, 'E trouxeram-no em cavalos, e sepultaram-no com seus pais na cidade de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 26, 1, 'Então todo o povo de Judá tomou a Uzias, o qual era de dezesseis anos, e puseram-no por rei em lugar de Amazias seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 26, 2, 'Edificou ele a Elote, e a restituiu a Judá depois que o rei descansou com seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 26, 3, 'De dezesseis anos era Uzias quando começou a reinar, e cinquenta e dois anos reinou em Jerusalém. O nome de sua mãe foi Jecolias, de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 26, 4, 'E fez o que era correto aos olhos do SENHOR, conforme a todas as coisas que havia feito Amazias seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 26, 5, 'E persistiu em buscar a Deus nos dias de Zacarias, entendido em visões de Deus; e nos dias que ele buscou ao SENHOR, ele lhe prosperou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 26, 6, 'E saiu, e lutou contra os filisteus, e rompeu o muro de Gate, e o muro de Jabné, e o muro de Asdode; e edificou cidades em Asdode, e na terra dos filisteus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 26, 7, 'E deu-lhe Deus ajuda contra os filisteus, e contra os árabes que habitavam em Gur-Baal, e contra os amonitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 26, 8, 'E os amonitas deram tributos a Uzias, e divulgou-se seu nome até a entrada do Egito; porque havia se tornado altamente poderoso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 26, 9, 'Edificou também Uzias torres em Jerusalém, junto à porta do ângulo, e junto à porta do vale, e junto às esquinas; e fortificou-as.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 26, 10, 'Assim edificou torres no deserto, e abriu muitas cisternas: porque teve muitos gados, assim nos vales como nas planícies; e vinhas, e lavouras, assim nos montes como nos campos férteis; porque era amigo da agricultura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 26, 11, 'Teve também Uzias esquadrões de guerreiros, os quais saíam à guerra em exército, segundo que estavam por lista feita por mão de Jeiel escriba e de Maaseias governador, e por mão de Hananias, um dos príncipes do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 26, 12, 'Todo o número dos chefes de famílias, valentes e esforçados, era dois mil e seiscentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 26, 13, 'E sob a mão destes estava o exército de guerra, de trezentos sete mil e quinhentos guerreiros poderosos e fortes para ajudar ao rei contra os inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 26, 14, 'E preparou-lhes Uzias para todo o exército, escudos, lanças, capacetes, couraças, arcos, e fundas de tirar pedras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 26, 15, 'E fez em Jerusalém máquinas por artifício de peritos, para que estivessem nas torres e nos baluartes, para lançar setas e grandes pedras, e sua fama se estendeu longe, porque se ajudou maravilhosamente, até fazer-se forte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 26, 16, 'Mas quando foi fortificado, seu coração se enalteceu até corromper-se; porque se rebelou contra o SENHOR seu Deus, entrando no templo do SENHOR para queimar incenso no altar do incenso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 26, 17, 'E entrou atrás dele o sacerdote Azarias, e com ele oitenta sacerdotes do SENHOR, dos valentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 26, 18, 'E puseram-se contra o rei Uzias, e disseram-lhe: Não a ti, ó Uzias, o queimar incenso ao SENHOR, mas sim aos sacerdotes filhos de Arão, que são consagrados para queimá-lo: sai do santuário, por que pecaste, e não te será para glória diante do SENHOR Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 26, 19, 'E irou-se Uzias, que tinha o incenso na mão para queimá-lo; e em esta sua ira contra os sacerdotes, a lepra lhe surgiu na testa diante dos sacerdotes na casa do SENHOR, junto ao altar do incenso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 26, 20, 'E olhou-lhe Azarias o sumo sacerdote, e todos os sacerdotes, e eis que a lepra estava em sua testa; e fizeram-lhe sair apressadamente daquele lugar; e ele também se deu pressa a sair, porque o SENHOR o havia ferido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 26, 21, 'Assim o rei Uzias foi leproso até o dia de sua morte, e habitou em uma casa separada, leproso, pelo que havia sido separado da casa do SENHOR; e Jotão seu filho teve cargo da casa real, governando ao povo da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 26, 22, 'Os demais dos feitos de Uzias, primeiros e últimos, escreveu-os Isaías profeta, filho de Amoz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 26, 23, 'E descansou Uzias com seus pais, e sepultaram-no com seus pais no campo dos sepulcros reais; porque disseram: Leproso é. E seu filho Jotão reinou Jotão em seu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 27, 1, 'De vinte e cinco anos era Jotão quando começou a reinar, e dezesseis anos reinou em Jerusalém. O nome de sua mãe foi Jerusa, filha de Zadoque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 27, 2, 'E fez o que era correto em olhos do SENHOR, conforme a todas as coisas que havia feito Uzias seu pai, salvo que não entrou no templo do SENHOR. E o povo corrompia-se ainda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 27, 3, 'Edificou ele a porta maior da casa do SENHOR, e no muro da fortaleza edificou muito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 27, 4, 'Ademais edificou cidades nas montanhas de Judá, e preparou palácios e torres nos bosques.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 27, 5, 'Também teve ele guerra com o rei dos filhos de Amom, aos quais venceu; e deram-lhe os filhos de Amom naquele ano cem talentos de prata, e dez mil coros de trigo, e dez mil de cevada. Isto lhe deram os filhos de Amom, e o mesmo no segundo ano, e no terceiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 27, 6, 'Assim que Jotão foi fortificado, porque preparou seus caminhos diante do SENHOR seu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 27, 7, 'Os demais dos feitos de Jotão, e todas suas guerras, e seus caminhos, eis que estão escrito no livro dos reis de Israel e de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 27, 8, 'Quando começou a reinar era de vinte e cinco anos, e dezesseis reinou em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 27, 9, 'E descansou Jotão com seus pais, e sepultaram-no na cidade de Davi; e reinou em seu lugar Acaz seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 28, 1, 'De vinte anos era Acaz quando começou a reinar, e dezesseis anos reinou em Jerusalém: mas não fez o que era correto aos olhos do SENHOR, como Davi seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 28, 2, 'Antes andou nos caminhos dos reis de Israel, e ademais fez imagens de fundição aos baalins.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 28, 3, 'Queimou também incenso no vale dos filhos de Hinom, e queimou seus filhos por fogo, conforme as abominações das nações que o SENHOR havia lançado diante dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 28, 4, 'Assim sacrificou e queimou incenso nos altos, e nas colinas, e debaixo de toda árvores espessa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 28, 5, 'Pelo qual o SENHOR seu Deus o entregou em mãos do rei dos sírios, os quais lhe derrotaram, e tomaram dele uma grande presa, que levaram a Damasco. Foi também entregue em mãos do rei de Israel, o qual o derrotou com grande mortandade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 28, 6, 'Porque Peca, filho de Remalias matou em Judá em um dia cento e vinte mil, todos eles homens valentes; porquanto haviam deixado ao SENHOR o Deus de seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 28, 7, 'Assim Zicri, homem poderoso de Efraim, matou a Maaseias filho do rei, e a Azricão seu mordomo, e a Elcana, segundo depois do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 28, 8, 'Tomaram também cativos os filhos de Israel de seus irmãos duzentos mil, mulheres, meninos, e meninas, a mais de haver saqueado deles um grande despojo, o qual trouxeram a Samaria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 28, 9, 'Havia então ali um profeta do SENHOR, que se chamava Obede, o qual saiu diante do exército quando entrava em Samaria, e disse-lhes: Eis que o SENHOR o Deus de vossos pais, pela ira contra Judá, os entregou em vossas mãos; e vós os'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 28, 10, 'E agora haveis determinado sujeitar a vós a Judá e a Jerusalém por servos e servas: mas não haveis vós pecado contra o SENHOR vosso Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 28, 11, 'Ouvi-me, pois, agora, e voltai a enviar os cativos que haveis tomado de vossos irmãos: porque o SENHOR está irado contra vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 28, 12, 'Levantaram-se então alguns homens dos principais dos filhos de Efraim, Azarias filho de Joanã, e Berequias filho de Mesilemote, e Jeizquias filho de Salum, e Amasa filho de Hadlai, contra os que vinham da guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 28, 13, 'E disseram-lhes: Não metais aqui os cativos; porque o pecado contra o SENHOR será sobre nós. Vós tratais de acrescentar sobre nossos pecados e sobre nossas culpas, sendo suficientemente grande nosso delito, e a ira do furor sobre Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 28, 14, 'Então o exército deixou os cativos e a presa diante dos príncipes e de toda a multidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 28, 15, 'E levantaram-se os homens nomeados, e tomaram os cativos, e vestiram do despojo aos que deles estavam nus; vestiram-nos e calçaram-nos, e deram-lhes de comer e de beber, e ungiram-nos, e conduziram em asnos a todos os fracos, e levaram-nos até Jericó, cidade das palmeiras, próxima de seus irmãos; e eles voltaram a Samaria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 28, 16, 'Naquele tempo enviou a pedir o rei Acaz aos reis de Assíria que lhe ajudassem:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 28, 17, 'Porque a mais disto, os edomitas haviam vindo e ferido aos de Judá, e haviam levado cativos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 28, 18, 'Assim os filisteus haviam invadido as cidades da planície, e ao sul de Judá, e haviam tomado a Bete-Semes, a Aijalom, Gederote, e Socó com suas aldeias, Timna também com suas aldeias, e Ginzo com suas aldeias; e habitavam nelas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 28, 19, 'Porque o SENHOR havia humilhado a Judá por causa de Acaz rei de Israel: porquanto ele havia desnudado a Judá, e rebelado-se gravemente contra o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 28, 20, 'E veio contra ele Tiglate-Pileser, rei dos assírios: pois o oprimiu, e não o fortificou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 28, 21, 'Ainda que Acaz tenha despojado a casa do SENHOR, e a casa real, e as dos príncipes, para dar ao rei dos assírios, contudo isso ele não lhe ajudou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 28, 22, 'Ademais o rei Acaz no tempo que aquele lhe afligia-se, acrescentou transgressão contra o SENHOR;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 28, 23, 'Porque sacrificou aos deuses de Damasco que lhe haviam ferido, e disse: Pois que os deuses dos reis da Síria lhes ajudam, eu também sacrificarei a eles para que me ajudem; bem que foram estes sua ruína, e a de todo Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 28, 24, 'A mais disso recolheu Acaz os vasos da casa de Deus, e quebrou-os, e fechou as portas da casa do SENHOR, e fez-se altares em Jerusalém em todos os cantos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 28, 25, 'Fez também altos em todas as cidades de Judá, para queimar incenso aos deuses alheios, provocando assim a ira ao SENHOR o Deus de seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 28, 26, 'Os demais de seus feitos, e todos seus caminhos, primeiros e últimos, eis que estão escrito no livro dos reis de Judá e de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 28, 27, 'E descansou Acaz com seus pais, e sepultaram-no na cidade de Jerusalém: mas não lhe meteram nos sepulcros dos reis de Israel; e reinou em seu lugar Ezequias seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 1, 'E Ezequias começou a reinar sendo de vinte e cinco anos, e reinou vinte e nove anos em Jerusalém. O nome de sua mãe foi Abia, filha de Zacarias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 2, 'E fez o que era correto aos olhos do SENHOR, conforme a todas as coisas que havia feito Davi seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 3, 'No primeiro ano de seu reinado, no mês primeiro, abriu as portas da casa do SENHOR, e as reparou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 4, 'E fez vir os sacerdotes e levitas, e juntou-os na praça oriental.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 5, 'E disse-lhes: Ouvi-me, levitas, e santificai-vos agora, e santificareis a casa do SENHOR o Deus de vossos pais, e tirareis do santuário a imundícia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 6, 'Porque nossos pais se rebelaram, e fizeram o que era mau aos olhos do SENHOR nosso Deus; que lhe deixaram, e apartaram seus olhos do tabernáculo do SENHOR, e lhe voltaram as costas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 7, 'E ainda fecharam as portas do pórtico, e apagaram as lâmpadas; não queimaram incenso, nem sacrificaram holocausto no santuário ao Deus de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 8, 'Portanto a ira do SENHOR veio sobre Judá e Jerusalém, e os entregou à aflição, ao espanto, e ao escárnio, como vedes vós com vossos olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 9, 'E eis que nossos pais caíram à espada, nossos filhos e nossas filhas e nossas mulheres estão em cativeiro por isso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 10, 'Agora, pois, eu determinei fazer aliança com o SENHOR o Deus de Israel, para que afaste de nós a ira de seu furor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 11, 'Filhos meus, não vos enganeis agora, porque o SENHOR vos escolheu para que estejais diante dele, e lhe sirvais, e sejais seus ministros, e lhe queimeis incenso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 12, 'Então os levitas se levantaram, Maate filho de Amasai, e Joel filho de Azarias, dos filhos de Coate; e dos filhos de Merari, Quis filho de Abdi, e Azarias filho de Jealelel; e dos filhos de Gérson, Joá filho de Zima, e Éden filho de Joá;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 13, 'E dos filhos de Elisafã, Sinri e Jeuel; e dos filhos de Asafe, Zacarias e Matanias;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 14, 'E dos filhos de Hemã, Jeiel e Simei; e dos filhos de Jedutum, Semaías e Uziel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 15, 'Estes juntaram a seus irmãos, e santificaram-se, e entraram, conforme ao mandamento do rei e as palavras do SENHOR, para limpar a casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 16, 'E entrando os sacerdotes dentro da casa do SENHOR para limpá-la, tiraram toda a imundícia que acharam no templo do SENHOR, ao átrio da casa do SENHOR; a qual tomaram os levitas, para tirá-la fora ao ribeiro de Cedrom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 17, 'E começaram a santificar o primeiro do mês primeiro, e aos oito do mesmo mês vieram ao pórtico do SENHOR: e santificaram a casa do SENHOR em oito dias, e no dezesseis do mês primeiro acabaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 18, 'Logo passaram ao rei Ezequias e disseram-lhe: Já limpamos toda a casa do SENHOR, o altar do holocausto, e todos seus instrumentos, e a mesa da proposição com todos seus utensílios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 19, 'Assim preparamos e santificamos todos os vasos que em sua transgressão havia descartado o rei Acaz, quando reinava: e eis que estão diante do altar do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 20, 'E levantando-se de manhã o rei Ezequias reuniu os principais da cidade, e subiu à casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 21, 'E apresentaram sete novilhos, sete carneiros, sete cordeiros, e sete bodes, para expiação pelo reino, pelo santuário e por Judá. E disse aos sacerdotes filhos de Arão, que os oferecessem sobre o altar do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 22, 'Mataram, pois, os bois, e os sacerdotes tomaram a sangue, e espargiram-na sobre o altar; mataram logo os carneiros, e espargiram o sangue sobre o altar; também mataram os cordeiros, e espargiram o sangue sobre o altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 23, 'Fizeram depois chegar os bodes da expiação diante do rei e da multidão, e puseram sobre eles suas mãos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 24, 'E os sacerdotes os mataram, e expiando espargiram o sangue deles sobre o altar, para reconciliar a todo Israel: porque por todo Israel mandou o rei fazer o holocausto e a expiação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 25, 'Pôs também levitas na casa do SENHOR com címbalos, e saltérios, e harpas, conforme ao mandamento de Davi, e de Gade vidente do rei, e de Natã profeta: porque aquele mandamento foi por mão do SENHOR, por meio de seus profetas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 26, 'E os levitas estavam com os instrumentos de Davi, e os sacerdotes com trombetas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 27, 'Então mandou Ezequias sacrificar o holocausto no altar; e ao tempo que começou o holocausto, começou também o cântico do SENHOR, com as trombetas e os instrumentos de Davi rei de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 28, 'E toda a multidão adorava, e os cantores cantavam, e os trombetas soavam as trombetas; tudo até acabar-se o holocausto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 29, 'E quando acabaram de oferecer, inclinou-se o rei, e todos os que com ele estavam, e adoraram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 30, 'Então o rei Ezequias e os príncipes disseram aos levitas que louvassem ao SENHOR pelas palavras de Davi e de Asafe vidente: e eles louvaram com grande alegria, e inclinando-se adoraram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 31, 'E respondendo Ezequias disse: Vós vos haveis consagrado agora ao SENHOR; achegai-vos pois, e apresentai sacrifícios e louvores na casa do SENHOR. E a multidão apresentou sacrifícios e louvores; e todo generoso de coração, holocaustos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 32, 'E foi o número dos holocaustos que trouxe a congregação, setenta bois, cem carneiros, duzentos cordeiros; tudo para o holocausto do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 33, 'E as ofertas foram seiscentos bois, e três mil ovelhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 34, 'Mas os sacerdotes eram poucos, e não podiam o suficiente a tirar o couro dos holocaustos; e assim seus irmãos os levitas lhes ajudaram até que acabaram a obra, e até que os sacerdotes se santificaram: porque os levitas tiveram maior prontidão de coração para se santificarem que os sacerdotes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 35, 'Assim, pois, havia grande abundância de holocaustos, com gorduras de ofertas pacíficas, e libações de cada holocausto. E ficou ordenado o serviço da casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 29, 36, 'E alegrou-se Ezequias, e todo o povo, de que Deus houvesse preparado o povo; porque a coisa foi prontamente feita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 30, 1, 'Enviou também Ezequias por todo Israel e Judá, e escreveu cartas a Efraim e Manassés, que viessem a Jerusalém à casa do SENHOR, para celebrar a páscoa ao SENHOR Deus de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 30, 2, 'E havia o rei tomado conselho com seus príncipes, e com toda a congregação em Jerusalém, para celebrar a páscoa no mês segundo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 30, 3, 'Porque então não a podiam celebrar, porquanto não havia suficientes sacerdotes santificados, nem o povo estava junto em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 30, 4, 'Isto agradou ao rei e a toda a multidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 30, 5, 'E determinaram fazer apregoar por todo Israel, desde Berseba até Dã, para que viessem a celebrar a páscoa ao SENHOR Deus de Israel, em Jerusalém: porque em muito tempo não a haviam celebrado ao modo que está escrito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 30, 6, 'Foram, pois, mensageiros com cartas da mão do rei e de seus príncipes por todo Israel e Judá, como o rei o havia mandado, e diziam: Filhos de Israel, voltai-vos ao SENHOR o Deus de Abraão, de Isaque, e de Israel, e ele se voltará aos restantes que vos escaparam das mãos dos reis da Assíria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 30, 7, 'Não sejais como vossos pais e como vossos irmãos, que se rebelaram contra o SENHOR o Deus de seus pais, e ele os entregou a desolação, como vós vedes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 30, 8, 'Não endureçais, pois, agora vossa cerviz como vossos pais: dai a mão ao SENHOR, e vinde a seu santuário, o qual ele santificou para sempre; e servi ao SENHOR vosso Deus, e a ira de seu furor se apartará de vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 30, 9, 'Porque se vos virardes ao SENHOR, vossos irmãos e vossos filhos acharão misericórdia diante dos que os têm cativos, e voltarão a esta terra: porque o SENHOR vosso Deus é clemente e misericordioso, e não desviará de vós seu rosto, se vós vos converterdes a ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 30, 10, 'Passaram, pois, os mensageiros de cidade em cidade pela terra de Efraim e Manassés, até Zebulom: mas se riam e ridicularizavam deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 30, 11, 'Com tudo isso, alguns homens de Aser, de Manassés, e de Zebulom, se humilharam, e vieram a Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 30, 12, 'Em Judá também foi a mão de Deus para dar-lhes um coração para cumprir a mensagem do rei e dos príncipes, conforme à palavra do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 30, 13, 'E juntou-se em Jerusalém muito gente para celebrar a solenidade dos pães ázimos no mês segundo; uma vasta reunião.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 30, 14, 'E levantando-se, tiraram os altares que havia em Jerusalém; tiraram também todos os altares de incenso, e lançaram-nos no ribeiro de Cedrom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 30, 15, 'Então sacrificaram a páscoa, aos catorze do mês segundo; e os sacerdotes e os levitas se santificaram com vergonha, e trouxeram os holocaustos à casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 30, 16, 'E puseram-se em sua ordem conforme a seu costume, conforme à lei de Moisés homem de Deus; os sacerdotes espargiam o sangue que recebiam de mãos dos levitas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 30, 17, 'Porque havia muitos na congregação que não estavam santificados, e por isso os levitas sacrificavam a páscoa por todos os que não se haviam limpado, para santificá-los ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 30, 18, 'Porque uma grande multidão do povo de Efraim e Manassés, e de Issacar e Zebulom, não se haviam purificado, e comeram a páscoa não conforme a o que está escrito. Mas Ezequias orou por eles, dizendo: SENHOR, que é bom, seja propício a todo aquele que preparou seu coração para buscar a Deus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 30, 19, 'Ao SENHOR, o Deus de seus pais, ainda que não esteja purificado segundo a purificação do santuário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 30, 20, 'E ouviu o SENHOR a Ezequias, e sarou o povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 30, 21, 'Assim celebraram os filhos de Israel que se acharam em Jerusalém, a solenidade dos pães sem levedura por sete dias com grande alegria: e louvavam ao SENHOR todos os dias os levitas e os sacerdotes, cantando com instrumentos de força ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 30, 22, 'E falou Ezequias ao coração de todos os levitas que tinham boa inteligência no serviço do SENHOR. E comeram do sacrificado na solenidade por sete dias, oferecendo sacrifícios pacíficos, e dando graças ao SENHOR o Deus de seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 30, 23, 'E toda aquela multidão determinou que celebrassem outros sete dias; e celebraram outros sete dias com alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 30, 24, 'Porque Ezequias rei de Judá havia dado à multidão mil novilhos e sete mil ovelhas; e também os príncipes deram ao povo mil novilhos e dez mil ovelhas: e muitos sacerdotes se santificaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 30, 25, 'Alegrou-se, pois, toda a congregação de Judá, como também os sacerdotes e levitas, e toda a multidão que havia vindo de Israel; assim os estrangeiros que haviam vindo da terra de Israel, e os que habitavam em Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 30, 26, 'E fizeram-se grandes alegrias em Jerusalém: porque desde os dias de Salomão filho de Davi rei de Israel, não havia havido coisa tal em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 30, 27, 'Levantando-se depois os sacerdotes e levitas, bendisseram ao povo: e a voz deles foi ouvida, e sua oração chegou à habitação de seu santuário, ao céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 31, 1, 'Feitas todas estas coisas, todos os de Israel que se haviam achado ali, saíram pelas cidades de Judá, e quebraram as estátuas e destruíram os bosques, e derrubaram os altos e os altares por todo Judá e Benjamim, e também em Efraim e Manassés,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 31, 2, 'E definiu Ezequias as repartições dos sacerdotes e dos levitas conforme a suas ordens, cada um segundo seu ofício, os sacerdotes e os levitas para o holocausto e pacíficos, para que ministrassem, para que confessassem e louvassem às portas dos acampamentos do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 31, 3, 'A contribuição do rei de sua riqueza era holocaustos a manhã e tarde, e holocaustos para os sábados, novas luas, e solenidades, como está escrito na lei do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 31, 4, 'Mandou também ao povo que habitava em Jerusalém, que dessem a porção aos sacerdotes e levitas, para que se esforçassem na lei do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 31, 5, 'E quando este edito foi divulgado, os filhos de Israel deram muitas primícias de grão, vinho, azeite, mel, e de todos os frutos da terra: trouxeram também os dízimos de todas as coisas em abundância.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 31, 6, 'Também os filhos de Israel e de Judá, que habitavam nas cidades de Judá, deram do mesmo modo os dízimos das vacas e das ovelhas: e trouxeram os dízimos do santificado, das coisas que haviam prometido ao SENHOR seu Deus, e puseram-nos por amontoados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 31, 7, 'No mês terceiro começaram a fundar aqueles amontoados, e no mês sétimo acabaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 31, 8, 'E Ezequias e os príncipes vieram a ver os amontoados, e bendisseram ao SENHOR, e a seu povo Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 31, 9, 'E perguntou Ezequias aos sacerdotes e aos levitas acerca dos amontoados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 31, 10, 'E respondeu-lhe Azarias, sumo sacerdote, da casa de Zadoque, e disse: Desde que começaram a trazer a oferta à casa do SENHOR, comemos e nos saciamos, e nos sobrou muito: porque o SENHOR abençoou seu povo, e restou esta abundância.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 31, 11, 'Então mandou Ezequias que preparassem câmaras na casa do SENHOR; e prepararam-nas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 31, 12, 'E puseram as primícias e dízimos e as coisas consagradas, fielmente; e deram cargo disso a Conanias levita, o principal, e Simei seu irmão foi o segundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 31, 13, 'E Jeiel, Azazias, Naate, Asael, Jeremote, Jozabade, Eliel, Ismaquias, Maate, e Benaia, foram capatazes sob a mão de Conanias e de Simei seu irmão, por mandamento do rei Ezequias e de Azarias, príncipe da casa de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 31, 14, 'E Coré filho de Imná levita, porteiro ao oriente, tinha cargo dos donativos de Deus, e das ofertas do SENHOR que se davam, e de tudo o que se santificava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 31, 15, 'E a sua mão estava Éden, Benjamim, Jesua, Semaías, Amarias, e Secanias, nas cidades dos sacerdotes, para dar com fidelidade a seus irmãos suas partes conforme a suas ordens, assim ao maior como ao menor:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 31, 16, 'A mais dos homens anotados por suas linhagens, de três anos acima, a todos os que entravam na casa do SENHOR, sua porção diária por seu ministério, segundo seus ofícios e classes;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 31, 17, 'Também aos que eram contados entre os sacerdotes pelas famílias de seus pais, e aos levitas de idade de vinte anos acima, conforme a seus ofícios e ordens;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 31, 18, 'Assim aos de sua geração com todos seus meninos, e suas mulheres, e seus filhos e filhas, a toda a família; porque com fidelidade se consagravam às coisas santas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 31, 19, 'Do mesmo modo em ordem aos filhos de Arão, sacerdotes, que estavam nos campos de suas cidades, por todas as cidades, os homens nomeados tinham cargo de dar suas porções a todos os homens dos sacerdotes, e a toda a linhagem dos levitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 31, 20, 'De esta maneira fez Ezequias em todo Judá: e executou o que era bom, correto, e verdadeiro, diante do SENHOR seu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 31, 21, 'Em tudo quanto começou no serviço da casa de Deus, e na lei e mandamentos, buscou a seu Deus, e o fez de todo coração, e foi próspero.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 1, 'Depois destas coisas e desta fidelidade, veio Senaqueribe rei dos assírios, entrou em Judá, e assentou campo contra as cidades fortes, e determinou de entrar nelas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 2, 'Vendo, pois, Ezequias a vinda de Senaqueribe, e seu aspecto de combater a Jerusalém,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 3, 'Teve seu conselho com seus príncipes e com seus valentes, sobre fechar as fontes das águas que estavam fora da cidade; e eles lhe apoiaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 4, 'Juntou-se, pois, muito povo, e fecharam todas as fontes, e o ribeiro que derrama por em meio do território, dizendo: Por que devem achar os reis de Assíria muitas águas quando vierem?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 5, 'Encorajou-se assim Ezequias, e edificou todos os muros caídos, e fez erguer as torres, e outro muro por de fora: fortificou também a Milo na cidade de Davi, e fez muitas espadas e paveses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 6, 'E pôs capitães de guerra sobre o povo, e os fez reunir assim na praça da porta da cidade, e falou ao coração deles, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 7, 'Esforçai-vos e confortai-vos; não temais, nem tenhais medo do rei da Assíria, nem de toda sua multidão que vem com ele; porque mais são conosco do que com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 8, 'Com ele está a força da carne, mas conosco está o SENHOR nosso Deus para ajudar-nos, e lutar nossas batalhas. E firmou-se o povo sobre as palavras de Ezequias rei de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 9, 'Depois disto Senaqueribe rei dos assírios, estando ele sobre Laquis e com ele toda sua potência, enviou seus servos a Jerusalém, para dizer a Ezequias rei de Judá, e a todos os de Judá que estavam em Jerusalém:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 10, 'Assim disse Senaqueribe rei dos assírios: Em quem confiais vós para estar cercados em Jerusalém?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 11, 'Não vos engana Ezequias para entregar-vos à morte, à fome, e à sede, dizendo: o SENHOR nosso Deus nos livrará da mão do rei da Assíria?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 12, 'Não é Ezequias o que tirou seus altos e seus altares, e disse a Judá e a Jerusalém: Diante somente deste altar adorareis, e sobre ele queimareis incenso?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 13, 'Não sabeis o que eu e meus pais fizemos a todos os povos da terra? Puderam os deuses das nações das terras livrar sua terra de minha mão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 14, 'Que deus havia de todos os deuses daquelas nações que destruíram meus pais, que pudesse salvar seu povo de minhas mãos? Por que poderá vosso Deus livrar-vos de minha mão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 15, 'Agora, pois, não vos engane Ezequias, nem vos persuada tal coisa, nem lhe creiais; que se nenhum deus de todas aquelas nações e reinos pode livrar seu povo de meus mãos, e das mãos de meus pais, quanto menos vosso Deus vos poderá livrar de minha mão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 16, 'E outras coisas falaram seus servos contra o Deus o SENHOR, e contra seu servo Ezequias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 17, 'Além de tudo isto escreveu cartas em que blasfemava ao SENHOR o Deus de Israel, e falava contra ele, dizendo: Como os deuses das nações dos países não puderam livrar seu povo de minhas mãos, tampouco o Deus de Ezequias livrará ao seu das minhas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 18, 'E clamaram a grande voz em judaico ao povo de Jerusalém que estava nos muros, para espantá-los e pôr-lhes temor, para tomar a cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 19, 'E falaram contra o Deus de Jerusalém, como contra os deuses dos povos da terra, obra de mãos de homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 20, 'Mas o rei Ezequias, e o profeta Isaías filho de Amoz, oraram por isto, e clamaram ao céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 21, 'E o SENHOR enviou um anjo, o qual feriu a todo valente e esforçado, e aos chefes e capitães no campo do rei da Assíria. Voltou-se, portanto, com vergonha de rosto a sua terra; e entrando no templo de seu deus, ali o mataram à espada os que haviam saído de suas entranhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 22, 'Assim o SENHOR salvou Ezequias e os moradores de Jerusalém das mãos de Senaqueribe rei da Assíria, e das mãos de todos: e preservou-os de todas as partes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 23, 'E muitos trouxeram oferta ao SENHOR a Jerusalém, e a Ezequias rei de Judá, ricos presentes; e foi muito grande diante de todas as nações depois disto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 24, 'Naquele tempo Ezequias ficou doente de morte; e orou ao SENHOR, o qual lhe respondeu, e deu-lhe um sinal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 25, 'Mas Ezequias não pagou conforme ao bem que lhe havia sido feito; pelo contrário, seu coração se enalteceu; por isso veio ira contra ele, e contra Judá e Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 26, 'Porém Ezequias, depois de haver-se orgulhado de coração, humilhou-se, ele e os moradores de Jerusalém; e não veio sobre eles a ira do SENHOR nos dias de Ezequias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 27, 'E Ezequias teve riquezas e glória em grande maneira; e proveu-se de tesouros de prata e ouro, de pedras preciosas, de aromas, de escudos, e de todas os tipos de objetos valiosos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 28, 'também de depósitos para as rendas do grão, do vinho, e azeite; estábulos para todo tipo de animais, e currais para os gados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 29, 'Fez para si também cidades, e rebanhos de ovelhas e de vacas em grande quantidade; porque Deus lhe havia dado muita riqueza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 30, 'Este Ezequias tapou os mananciais das águas de Giom da parte de cima, e as fez correr abaixo ao ocidente da cidade de Davi. E foi próspero Ezequias em tudo o que fez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 31, 'Porém no dos embaixadores dos príncipes de Babilônia, que enviaram a ele para saber do prodígio que havia acontecido naquela terra, Deus o deixou, para provar-lhe, para fazer conhecer tudo o que estava em seu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 32, 'Os demais dos feitos de Ezequias, e de suas misericórdias, eis que tudo está escrito na profecia de Isaías profeta, filho de Amoz, no livro dos reis de Judá e de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 32, 33, 'E descansou Ezequias com seus pais, e sepultaram-no na parte superior dos sepulcros dos filhos de Davi, honrando-lhe em sua morte todo Judá e os de Jerusalém: e reinou em seu lugar Manassés seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 33, 1, 'De doze anos era Manassés quando começou a reinar, e cinquenta e cinco anos reinou em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 33, 2, 'Mas fez o que era mau em olhos do SENHOR, conforme as abominações das nações que havia lançado o SENHOR diante dos filhos de Israel:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 33, 3, 'Porque ele reedificou os altos que Ezequias seu pai havia derrubado, e levantou altares aos baalins, e fez bosques, e adorou a todo o exército dos céus, e a ele serviu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 33, 4, 'Edificou também altares na casa do SENHOR, da qual havia dito o SENHOR: Em Jerusalém será meu nome perpetuamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 33, 5, 'Edificou assim altares a todo o exército dos céus nos dois átrios da casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 33, 6, 'E passou seus filhos por fogo no vale dos filhos de Hinom; e olhava adivinhações, predições supersticiosas, e feitiçarias, e consultava médiuns e interpretadores de espíritos; ele fez muito mal aos olhos do SENHOR, para irritar-lhe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 33, 7, 'A mais disto pôs uma imagem de fundição, que fez, na casa de Deus, da qual havia dito Deus a Davi e a Salomão seu filho: Nesta casa e em Jerusalém, a qual eu escolhi sobre todas as tribos de Israel, porei meu nome para sempre:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 33, 8, 'E nunca mais tirarei o pé de Israel da terra que eu entreguei a vossos pais, a condição que guardem e façam todas as coisas que eu lhes ei mandado, toda a lei, estatutos, e ordenanças, por meio de Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 33, 9, 'Fez, pois, Manassés desviar-se a Judá e aos moradores de Jerusalém, para fazer mais mal que as nações que o SENHOR destruiu diante dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 33, 10, 'E falou o SENHOR a Manassés e a seu povo, mas eles não escutaram:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 33, 11, 'Por isso o SENHOR trouxe contra eles os generais do exército do rei dos assírios, os quais aprisionaram com grilhões a Manassés, e acorrentado com correntes levaram-no a Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 33, 12, 'Mas logo que foi posto em angústias, orou ante o SENHOR seu Deus, humilhado grandemente na presença do Deus de seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 33, 13, 'E havendo a ele orado, foi atendido; pois que ouviu sua oração, e voltou-o a Jerusalém, a seu reino. Então conheceu Manassés que o SENHOR era Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 33, 14, 'Depois disto edificou o muro de fora da cidade de Davi, ao ocidente de Giom, no vale, à entrada da porta do peixe, e cercou a Ofel, e levantou-o muito alto; e pôs capitães de exército em todas as cidades fortes por Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 33, 15, 'Também tirou os deuses alheios, e o ídolo da casa do SENHOR, e todos os altares que havia edificado no monte da casa do SENHOR e em Jerusalém, e lançou-os fora da cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 33, 16, 'Reparou logo o altar do SENHOR, e sacrificou sobre ele sacrifícios pacíficos e de louvor; e mandou a Judá que servissem ao SENHOR Deus de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 33, 17, 'Porém o povo ainda sacrificava nos altos, ainda que somente ao SENHOR seu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 33, 18, 'Os demais dos feitos de Manassés, e sua oração a seu Deus, e as palavras dos videntes que lhe falaram em nome do SENHOR o Deus de Israel, eis que tudo está escrito nos feitos dos reis de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 33, 19, 'Sua oração também, e como foi ouvido, todos seus pecados, e sua transgressão, os lugares de onde edificou altos e havia posto bosques e ídolos antes que se humilhasse, eis que estas coisas estão escritas nas palavras dos videntes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 33, 20, 'E descansou Manassés com seus pais, e sepultaram-no em sua casa: e reinou em seu lugar Amom seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 33, 21, 'De vinte e dois anos era Amom quando começou a reinar, e dois anos reinou em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 33, 22, 'E fez o que era mau em olhos do SENHOR, como havia feito Manassés seu pai: porque a todos os ídolos que seu pai Manassés havia feito, sacrificou e serviu Amom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 33, 23, 'Mas nunca se humilhou diante do SENHOR, como se humilhou Manassés seu pai: antes aumentou o pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 33, 24, 'E conspiraram contra ele seus servos, e mataram-no em sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 33, 25, 'Mas o povo da terra feriu a todos os que haviam conspirado contra o rei Amom; e o povo da terra pôs por rei em seu lugar a Josias seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 1, 'De oito anos era Josias quando começou a reinar, e trinta e um anos reinou em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 2, 'Este fez o que era correto aos olhos do SENHOR, e andou nos caminhos de Davi seu pai, sem desviar-se à direita nem à esquerda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 3, 'A os oito anos de seu reinado, sendo ainda jovem, começou a buscar ao Deus de Davi seu pai; e aos doze anos começou a limpar a Judá e a Jerusalém dos altos, bosques, esculturas, e imagens de fundição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 4, 'E derrubaram diante dele os altares dos baalins, e fez pedaços as imagens do sol, que estavam postas encima; despedaçou também os bosques, e as esculturas e estátuas de fundição, e esmigalhou-as, e dispersou o pó sobre os sepulcros dos que a elas haviam sacrificado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 5, 'Queimou ademais os ossos dos sacerdotes sobre seus altares, e limpou a Judá e a Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 6, 'O mesmo fez nas cidades de Manassés, Efraim, e Simeão, até em Naftali, com seus lugares assolados ao redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 7, 'E quando havia derrubado os altares e os bosques, e quebrado e esmigalhado as esculturas, e destruído todos os ídolos por toda a terra de Israel, voltou-se a Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 8, 'Aos dezoito anos de seu reinado, depois de haver limpado a terra, e a casa, enviou a Safã filho de Azalias, e a Maaseias governador da cidade, e a Joá filho de Jeoacaz, chanceler, para que reparassem a casa do SENHOR seu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 9, 'Os quais vieram a Hilquias, grande sacerdote, e deram o dinheiro que havia sido posto na casa do SENHOR, que os levitas que guardavam a porta haviam recolhido da mão de Manassés e de Efraim e de todas as restantes de Israel, e de todo Judá e Benjamim, havendo depois voltado a Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 10, 'E entregaram-no em mão dos que faziam a obra, que eram capatazes na casa do SENHOR; os quais o davam aos que faziam a obra e trabalhavam na casa do SENHOR, para reparar e restaurar o templo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 11, 'Davam também aos oficiais e pedreiros para que comprassem pedra lavrada, e madeira para as juntas, e para cobertura das casas, as quais haviam destruído os reis de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 12, 'E estes homens procediam com fidelidade na obra: e eram seus governadores Jaate e Obadias, levitas dos filhos de Merari; e Zacarias e Mesulão dos filhos de Coate, para que ativassem a obra; e dos levitas, todos os entendidos em instrumentos musicais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 13, 'Também supervisionavam sobre os operários, e eram capatazes dos que se ocupavam em qualquer classe de obra; e dos levitas havia escribas, governadores, e porteiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 14, 'E ao tirar o dinheiro que havia sido posto na casa do SENHOR, Hilquias o sacerdote achou o livro da lei do SENHOR dada por meio de Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 15, 'E dando conta Hilquias, disse a Safã escriba: Eu ei achado o livro da lei na casa do SENHOR. E deu Hilquias o livro a Safã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 16, 'E Safã o levou ao rei, e contou-lhe o negócio, dizendo: Teus servos cumpriram tudo o que lhes foi encarregado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 17, 'Reuniram o dinheiro que se achou na casa do SENHOR, e o entregaram em mão dos comissionados, e em mão dos que fazem a obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 18, 'A mais disto, declarou Safã escriba ao rei, dizendo: O sacerdote Hilquias me deu um livro. E leu Safã nele diante do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 19, 'E logo que o rei ouviu as palavras da lei, rasgou suas vestes;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 20, 'E mandou a Hilquias e a Aicã filho de Safã, e a Abdom filho de Mica, e a Safã escriba, e a Asaías servo do rei, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 21, 'Andai, e consultai ao SENHOR de mim, e dos restantes de Israel e de Judá, acerca das palavras do livro que se achou; porque grande é o furor do SENHOR que há caído sobre nós, porquanto nossos pais não guardaram a palavra do SENHOR, para fazer conforme tudo o que está escrito neste livro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 22, 'Então Hilquias e os do rei foram a Hulda profetisa, mulher de Salum, filho de Tocate, filho de Harás, guarda das vestimentas, a qual morava em Jerusalém na segunda parte [da cidade] e disseram-lhe as palavras ditas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 23, 'E ela respondeu: o SENHOR o Deus de Israel disse assim: Dizei ao homem que vos enviou a mim, que assim disse o SENHOR:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 24, 'Eis que eu trago mal sobre este lugar, e sobre os moradores dele, e todas as maldições que estão escritas no livro que leram diante do rei de Judá:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 25, 'Por quanto me deixaram, e sacrificaram a deuses alheios, provocando-me à ira em todas as obras de suas mãos; portanto meu furor destilará sobre este lugar, e não se apagará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 26, 'Mas ao rei de Judá, que vos enviou a consultar ao SENHOR, assim lhe direis: o SENHOR o Deus de Israel disse assim: Porquanto ouviste as palavras do livro,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 27, 'E teu coração se enterneceu, e te humilhaste diante de Deus ao ouvir suas palavras sobre este lugar, e sobre seus moradores, e te humilhaste diante de mim, e rasgaste tuas vestes, e choraste em minha presença, eu também te ei ouvido, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 28, 'Eis que eu te recolherei com teus pais, e serás recolhido em teus sepulcros em paz, e teus olhos não verão todo o mal que eu trago sobre este lugar, e sobre os moradores dele. E eles referiram ao rei a resposta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 29, 'Então o rei enviou e juntou todos os anciãos de Judá e de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 30, 'E subiu o rei à casa do SENHOR, e com ele todos os homens de Judá, e os moradores de Jerusalém, e os sacerdotes, e os levitas, e todo o povo desde o maior até o menor; e leu a ouvidos deles todas as palavras do livro do pacto que havia sido achado na casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 31, 'E estando o rei em pé em seu lugar, fez aliança diante do SENHOR de caminhar após o SENHOR, e de guardar seus mandamentos, seus testemunhos, e seus estatutos, de todo seu coração e de toda sua alma, praticando as palavras do pacto que estavam escritas naquele livro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 32, 'E fez que se obrigassem a ele todos os que estavam em Jerusalém e em Benjamim: e os moradores de Jerusalém fizeram conforme ao pacto de Deus, do Deus de seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 34, 33, 'E tirou Josias todas as abominações de todas as terras dos filhos de Israel, e fez a todos os que se acharam em Israel servirem ao SENHOR seu Deus. Não se desviaram de seguir o SENHOR o Deus de seus pais, todo o tempo que ele viveu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 35, 1, 'E Josias fez páscoa ao SENHOR em Jerusalém, e sacrificaram a páscoa aos catorze do mês primeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 35, 2, 'E pôs aos sacerdotes em seus empregos, e confirmou-os no ministério da casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 35, 3, 'E disse aos levitas que ensinavam a todo Israel, e que estavam dedicados ao SENHOR: Ponde a arca do santuário na casa que edificou Salomão filho de Davi, rei de Israel, para que não a carregueis mais sobre os ombros. Agora servireis ao SENHOR vosso Deus, e a seu povo Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 35, 4, 'Preparai-vos segundo as famílias de vossos pais, por vossas ordens, conforme à prescrição de Davi rei de Israel, e de Salomão seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 35, 5, 'Ficai no santuário segundo a distribuição das famílias de vossos irmãos os filhos do povo, e segundo a divisão da família dos levitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 35, 6, 'Sacrificai logo a páscoa: e depois de santificar-vos, preparai a vossos irmãos, para que façam conforme à palavra do SENHOR dada por meio de Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 35, 7, 'E o rei Josias deu ao povo ovelhas, cordeiros, e cabritos dos rebanhos, em número de trinta mil, e três mil bois, tudo para a páscoa, para todos os que estavam presentes: isto era do patrimônio do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 35, 8, 'Também seus oficiais doaram com generosidade ao povo, e aos sacerdotes e levitas. Hilquias, Zacarias e Jeiel, líderes da casa de Deus, deram aos sacerdotes para fazer a páscoa duas mil e seiscentos , e trezentos bois.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 35, 9, 'Também Conanias, e Semaías e Natanael, seus irmãos, e Hasabias, Jeiel, e Jozabade, chefes dos levitas, deram aos levitas para os sacrifícios da páscoa cinco mil , e quinhentos bois.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 35, 10, 'Prontificado assim o serviço, os sacerdotes se colocaram em seus postos, e também os levitas em suas ordens, conforme ao mandamento do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 35, 11, 'E sacrificaram a páscoa; e os sacerdotes espargiam o sangue tomado da mão dos levitas, e os levitas tiravam os couros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 35, 12, 'E tomaram do holocausto, para dar conforme as repartições pelas famílias dos do povo, a fim de que oferecessem ao SENHOR, segundo está escrito no livro de Moisés; e também tomaram dos bois.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 35, 13, 'E assaram a páscoa ao fogo segundo o rito; mas o que havia sido santificado o cozinharam em panelas, em caldeiras, e caldeirões, e repartiram-no o prontamente a todo o povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 35, 14, 'E depois prepararam para si e para os sacerdotes; porque os sacerdotes, filhos de Arão, estiveram ocupados até a noite no sacrifício dos holocaustos e das gorduras; portanto, os levitas prepararam para si, e para os sacerdotes filhos de Arão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 35, 15, 'Também os cantores filhos de Asafe estavam em seu posto, conforme ao mandamento de Davi, de Asafe e de Hemã, e de Jedutum vidente do rei; também os porteiros estavam a cada porta; e não era necessário que se afastassem de seu ministério, porque seus irmãos, os levitas, preparavam para eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 35, 16, 'Assim foi aprontei todo o serviço do SENHOR naquele dia, para fazer a páscoa, e sacrificar os holocaustos sobre o altar do SENHOR, conforme ao mandamento do rei Josias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 35, 17, 'E os filhos de Israel que se acharam ali, fizeram a páscoa naquele tempo, e a solenidade dos pães sem levedura, por sete dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 35, 18, 'Nunca tal páscoa foi feita em Israel desde os dias de Samuel o profeta; nem nenhum rei de Israel fez páscoa tal como a que fez o rei Josias, e os sacerdotes e levitas, e todo Judá e Israel, os que se acharam ali, juntamente com os moradores de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 35, 19, 'Esta páscoa foi celebrada no ano dezoito do rei Josias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 35, 20, 'Depois de todas estas coisas, logo de haver Josias preparado a casa, Neco rei do Egito subiu a fazer guerra em Carquêmis junto a Eufrates; e saiu Josias contra ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 35, 21, 'E ele lhe enviou embaixadores, dizendo: Que temos eu e tu, rei de Judá? Eu não venho contra ti hoje, mas sim contra a casa que me faz guerra: e Deus disse que me apressasse. Deixa-te de intrometer-te com Deus, que é comigo, não te destrua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 35, 22, 'Mas Josias não voltou seu rosto dele, em vez disso disfarçou-se para dar-lhe batalha, e não atendeu às palavras de Neco, que eram da boca de Deus; e veio a dar-lhe a batalha no campo de Megido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 35, 23, 'E os arqueiros atiraram ao rei Josias flechas; e disse o rei a seus servos: Tirai-me daqui, porque estou ferido gravemente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 35, 24, 'Então seus servos o tiraram daquele carro, e puseram-lhe em outro segundo carro que tinha, e levaram-lhe a Jerusalém, e morreu; e sepultaram-lhe nos sepulcros de seus pais. E todo Judá e Jerusalém fez luto por Josias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 35, 25, 'E lamentou Jeremias por Josias, e todos os cantores e cantoras recitam suas lamentações sobre Josias até hoje; e as deram por norma para lamentar em Israel, as quais estão escritas nas Lamentações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 35, 26, 'Os demais dos feitos de Josias, e suas piedosas obras, conforme o que está escrito na lei do SENHOR,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 35, 27, 'E seus feitos, primeiros e últimos, eis que estão escritos no livro dos reis de Israel e de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 36, 1, 'Então o povo da terra tomou a Jeoacaz filho de Josias, e fizeram-lhe rei em lugar de seu pai em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 36, 2, 'De vinte e três anos era Jeoacaz quando começou a reinar, e três meses reinou em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 36, 3, 'E o rei do Egito o tirou de Jerusalém, e condenou a terra em cem talentos de prata e um de ouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 36, 4, 'E o rei do Egito constituiu o seu irmão Eliaquim como rei sobre Judá e Jerusalém, e mudou-lhe o nome em Jeoaquim; e Neco tomou o seu irmão Jeoacaz, e o levou ao Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 36, 5, 'Quando começou a reinar Jeoaquim era de vinte e cinco anos, e reinou onze anos em Jerusalém: e fez o que era mau aos olhos do SENHOR seu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 36, 6, 'E subiu contra ele Nabucodonosor rei da Babilônia, e acorrentado com correntes o levou à Babilônia.')
